/* A record of a buffer (the payload points into the buffer). */
typedef struct DbmRecord
{
    uint16_t id;
    uint8_t type;
    uint8_t op;
    uint16_t idx[4];
    uint32_t len;
    uint8_t value[8];
    const uint8_t *payload;
} DbmRecord;

/* A writer on a buffer of the host. `size` is the used size; a record which does not fit sets
   `overflow` (the buffer then holds the records before it). */
typedef struct DbmWriter
{
    uint8_t *data;
    size_t size;
    size_t capacity;
    int overflow;
} DbmWriter;

static inline void dbm_put_u16 (uint8_t *p, uint16_t v) { p[0] = (uint8_t) v; p[1] = (uint8_t) (v >> 8); }
static inline void dbm_put_u32 (uint8_t *p, uint32_t v) { dbm_put_u16 (p, (uint16_t) v); dbm_put_u16 (p + 2, (uint16_t) (v >> 16)); }
static inline uint16_t dbm_get_u16 (const uint8_t *p) { return (uint16_t) (p[0] | (p[1] << 8)); }
static inline uint32_t dbm_get_u32 (const uint8_t *p) { return (uint32_t) dbm_get_u16 (p) | ((uint32_t) dbm_get_u16 (p + 2) << 16); }

/* Start a buffer: writes the header. */
static inline void dbm_writer_init (DbmWriter *w, uint8_t *data, size_t capacity)
{
    w->data = data;
    w->capacity = capacity;
    w->size = 0;
    w->overflow = capacity < DBM_HEADER_SIZE;
    if (w->overflow)
        return;
    memcpy (data, "DBM1", 4);
    dbm_put_u16 (data + 4, DBM_PROTOCOL_VERSION_MAJOR);
    dbm_put_u16 (data + 6, 0);
    w->size = DBM_HEADER_SIZE;
}

/* Append a record: the indices i0..i3, the 8 bytes of the inline value (or null) and the
   payload. Returns 0 if it does not fit. */
static inline int dbm_put (DbmWriter *w, uint16_t id, uint8_t type, uint8_t op, uint16_t i0, uint16_t i1, uint16_t i2, uint16_t i3, const uint8_t *value, const void *payload, uint32_t len)
{
    size_t padded = (len + 7u) & ~(size_t) 7u;
    if (w->overflow || w->size + DBM_RECORD_SIZE + padded > w->capacity)
    {
        w->overflow = 1;
        return 0;
    }
    uint8_t *p = w->data + w->size;
    dbm_put_u16 (p, id);
    p[2] = type;
    p[3] = op;
    dbm_put_u16 (p + 4, i0);
    dbm_put_u16 (p + 6, i1);
    dbm_put_u16 (p + 8, i2);
    dbm_put_u16 (p + 10, i3);
    dbm_put_u32 (p + 12, len);
    if (value != NULL)
        memcpy (p + 16, value, 8);
    else
        memset (p + 16, 0, 8);
    if (len > 0)
        memcpy (p + DBM_RECORD_SIZE, payload, len);
    memset (p + DBM_RECORD_SIZE + len, 0, padded - len);
    w->size += DBM_RECORD_SIZE + padded;
    return 1;
}

static inline int dbm_put_none (DbmWriter *w, uint16_t id, uint16_t i0, uint16_t i1, uint16_t i2, uint16_t i3)
{
    return dbm_put (w, id, DBM_TYPE_NONE, DBM_OP_SET, i0, i1, i2, i3, NULL, NULL, 0);
}

static inline int dbm_put_i64 (DbmWriter *w, uint16_t id, uint8_t type, uint16_t i0, uint16_t i1, uint16_t i2, uint16_t i3, int64_t v)
{
    uint8_t value[8];
    for (int i = 0; i < 8; i++)
        value[i] = (uint8_t) ((uint64_t) v >> (8 * i));
    return dbm_put (w, id, type, DBM_OP_SET, i0, i1, i2, i3, value, NULL, 0);
}

static inline int dbm_put_bool (DbmWriter *w, uint16_t id, uint16_t i0, uint16_t i1, uint16_t i2, uint16_t i3, int v)
{
    return dbm_put_i64 (w, id, DBM_TYPE_BOOL, i0, i1, i2, i3, v ? 1 : 0);
}

static inline int dbm_put_i32 (DbmWriter *w, uint16_t id, uint16_t i0, uint16_t i1, uint16_t i2, uint16_t i3, int32_t v)
{
    return dbm_put_i64 (w, id, DBM_TYPE_I32, i0, i1, i2, i3, v);
}

static inline int dbm_put_f64 (DbmWriter *w, uint16_t id, uint16_t i0, uint16_t i1, uint16_t i2, uint16_t i3, double v)
{
    uint8_t value[8];
    memcpy (value, &v, 8); /* all targets are little-endian */
    return dbm_put (w, id, DBM_TYPE_F64, DBM_OP_SET, i0, i1, i2, i3, value, NULL, 0);
}

static inline int dbm_put_text (DbmWriter *w, uint16_t id, uint16_t i0, uint16_t i1, uint16_t i2, uint16_t i3, const char *text, uint32_t len)
{
    return dbm_put (w, id, DBM_TYPE_TEXT, DBM_OP_SET, i0, i1, i2, i3, NULL, text, len);
}

/* A color 0..255 each; valid = 0: no color. */
static inline int dbm_put_color (DbmWriter *w, uint16_t id, uint16_t i0, uint16_t i1, uint16_t i2, uint16_t i3, uint8_t r, uint8_t g, uint8_t b, int valid)
{
    uint8_t value[8] = { r, g, b, (uint8_t) (valid ? 1 : 0), 0, 0, 0, 0 };
    return dbm_put (w, id, DBM_TYPE_COLOR, DBM_OP_SET, i0, i1, i2, i3, value, NULL, 0);
}

/* Check the header of a buffer; returns the position of the first record or 0. */
static inline size_t dbm_check_header (const uint8_t *buffer, size_t length)
{
    if (length < DBM_HEADER_SIZE || memcmp (buffer, "DBM1", 4) != 0 || dbm_get_u16 (buffer + 4) != DBM_PROTOCOL_VERSION_MAJOR)
        return 0;
    return DBM_HEADER_SIZE;
}

/* Read the record at *pos and advance *pos; returns 0 at the end (or for a truncated record).
   Start with *pos = dbm_check_header (buffer, length). */
static inline int dbm_next_record (const uint8_t *buffer, size_t length, size_t *pos, DbmRecord *record)
{
    if (*pos == 0 || *pos + DBM_RECORD_SIZE > length)
        return 0;
    const uint8_t *p = buffer + *pos;
    record->len = dbm_get_u32 (p + 12);
    if (*pos + DBM_RECORD_SIZE + record->len > length)
        return 0;
    record->id = dbm_get_u16 (p);
    record->type = p[2];
    record->op = p[3];
    for (int i = 0; i < 4; i++)
        record->idx[i] = dbm_get_u16 (p + 4 + 2 * i);
    memcpy (record->value, p + 16, 8);
    record->payload = p + DBM_RECORD_SIZE;
    *pos += DBM_RECORD_SIZE + ((record->len + 7u) & ~(size_t) 7u);
    if (*pos > length)
        *pos = length;
    return 1;
}

static inline int64_t dbm_record_i64 (const DbmRecord *record)
{
    uint64_t v = 0;
    for (int i = 7; i >= 0; i--)
        v = (v << 8) | record->value[i];
    return (int64_t) v;
}

static inline double dbm_record_f64 (const DbmRecord *record)
{
    double v;
    memcpy (&v, record->value, 8);
    return v;
}

#endif /* DBM_PROTOCOL_H */
